/*
 * Held UI dev server — serves wled00/data/held straight from source (no build, no flashing).
 *
 *   npm run held:sim                          simulator only, http://localhost:8080
 *   npm run held:sim -- --device 192.168.1.50 also proxy the JSON API / settings pages to a controller
 *   npm run held:sim -- --port 9000
 *
 * Without --device the page runs as a simulator. You can also just open
 * wled00/data/held/index.htm directly from disk.
 */
'use strict';
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

const args = process.argv.slice(2);
const opt = (name, def) => { const i = args.indexOf('--' + name); return i >= 0 && args[i + 1] ? args[i + 1] : def; };
const PORT = Number(opt('port', 8080));
const DEVICE = opt('device', null);
const ROOT = path.join(__dirname, '..', '..', 'wled00', 'data', 'held');
const TYPES = { '.htm': 'text/html', '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.json': 'application/json', '.ico': 'image/x-icon' };

function proxy(req, res) {
  const up = http.request({ host: DEVICE, port: 80, path: req.url, method: req.method, headers: Object.assign({}, req.headers, { host: DEVICE }) }, (r) => {
    res.writeHead(r.statusCode, r.headers);
    r.pipe(res);
  });
  up.on('error', (e) => { res.writeHead(502, { 'Content-Type': 'text/plain' }); res.end('device unreachable: ' + e.message); });
  req.pipe(up);
}

http.createServer((req, res) => {
  const url = new URL(req.url, 'http://x');
  let p = decodeURIComponent(url.pathname);
  if (p === '/') p = '/index.htm';
  const file = path.join(ROOT, path.normalize(p).replace(/^([/\\])+/, ''));
  if (file.startsWith(ROOT) && fs.existsSync(file) && fs.statSync(file).isFile()) {
    res.writeHead(200, { 'Content-Type': TYPES[path.extname(file)] || 'application/octet-stream', 'Cache-Control': 'no-store' });
    fs.createReadStream(file).pipe(res);
    return;
  }
  if (DEVICE) return proxy(req, res);
  res.writeHead(404, { 'Content-Type': 'text/plain' });
  res.end('not found (simulator mode - start with --device <ip> to proxy to a controller)');
}).listen(PORT, () => {
  console.log(`Held UI: http://localhost:${PORT}/` + (DEVICE ? `  (API proxied to ${DEVICE}; live LED view connects to ws://${DEVICE}/ws directly)` : '  (simulator)'));
});
